  "form.tc.title": { es: "Términos y Condiciones de Uso", en: "Terms and Conditions of Use" },
  "form.tc.close": { es: "Entendido y Cerrar", en: "Understood and Close" },
  "form.tc.c3_title": { es: "3. Contrato de Corretaje Digital (Plan Éxito Compartido)", en: "3. Digital Brokerage Contract (Shared Success Plan)" },
  "form.tc.c3_1_title": { es: "3.1. Reconocimiento de Intermediación", en: "3.1. Intermediation Recognition" },
  "form.tc.c3_1_desc": { es: "El Usuario reconoce y acepta que Nuevo Sol Inversiones y sus agentes automatizados actúan como corredores inmobiliarios oficiales. La firma digital de estos términos posee plena validez jurídica conforme a la Ley 126-02 de Comercio Electrónico de la República Dominicana.", en: "The User acknowledges and accepts that Nuevo Sol Inversiones and its automated agents act as official real estate brokers. The digital signature of these terms has full legal validity under Law 126-02 of Electronic Commerce of the Dominican Republic." },
  "form.tc.c3_2_title": { es: "3.2. Estructura de Pagos y Facturación", en: "3.2. Fee Structure & Invoicing" },
  "form.tc.c3_2_desc": { es: "Al optar por el plan gratuito, el propietario se compromete a pagar una comisión del <strong>3% para propiedades urbanas residenciales</strong> y del <strong>5% para terrenos o propiedades rurales</strong>. Esta comisión está sujeta al pago del 18% de ITBIS (Normativas DGII) y será pagadera a la firma del Contrato de Promesa de Venta o al recibo del pago mayoritario.", en: "By opting for the free plan, the owner agrees to pay a commission of <strong>3% for urban residential properties</strong> and <strong>5% for land or rural properties</strong>. This commission is subject to the 18% ITBIS tax (DGII Regulations) and shall be payable upon signing the Promise of Sale Contract or upon receipt of the majority payment." },
  "form.tc.c3_3_title": { es: "3.3. Certificado de Visita Digital", en: "3.3. Digital Visit Certificate" },
  "form.tc.c3_3_desc": { es: "La IA generará un \"Certificado de Visita Digital\" por cada lead calificado (verificando Cédula/Pasaporte). Si dicho prospecto figura en el Registro de Títulos (Ley 108-05) como adquiriente, será prueba legal de nuestra intermediación.", en: "The AI will generate a \"Digital Visit Certificate\" for each qualified lead (verifying ID/Passport). If such prospect appears in the Registry of Titles (Law 108-05) as the acquirer, it will be legal proof of our intermediation." },
  "form.tc.c3_4_title": { es: "3.4. Cláusula de Extensión (Derecho Post-Terminación)", en: "3.4. Extension Clause (Post-Termination Right)" },
  "form.tc.c3_4_desc": { es: "El derecho a la comisión se extiende por <strong>doce (12) meses</strong> tras la baja del anuncio si el comprador es un prospecto originalmente presentado por la plataforma.", en: "The right to commission extends for <strong>twelve (12) months</strong> after the listing is removed if the buyer is a prospect originally introduced by the platform." },
  "form.tc.c3_5_title": { es: "3.5. Penalidades por Evasión", en: "3.5. Penalties for Evasion" },
  "form.tc.c3_5_desc": { es: "Si se concreta la venta con un prospecto de la plataforma ocultándolo para evadir el pago, el usuario deberá pagar una penalidad equivalente al <strong>doble (200%)</strong> de la tarifa original en concepto de daños y perjuicios.", en: "If the sale is finalized with a prospect from the platform while hiding it to evade payment, the user must pay a penalty equivalent to <strong>double (200%)</strong> the original fee as damages." },

